/**
 * The hand-written core of the book.
 *
 * These are the openings a player actually chooses between, each with the ideas
 * that make it playable rather than just the move order. The full ECO tables
 * (3,810 lines) are imported separately into `eco.generated.ts` and merged in
 * `book.ts`; theory is the part that cannot be imported, so it is written here
 * and inherited downwards by every ECO line beneath it.
 */

import type { Opening, OpeningTheory } from './types.js';

const line = (moves: string): string[] => moves.split(' ').filter(Boolean);

